package io.github.yuroyami.kiteimage

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/**
 * JPEG vectors: encoded by ffmpeg (an unrelated encoder), ground truth decoded
 * by the real stb_image compiled with clang (`stb_dump.c`, STBI_NO_SIMD). The
 * port is a faithful line-for-line translation of stb's scalar kernels, so the
 * assertion is BIT-EXACT equality: any drift from the reference is a bug.
 */
class JpegDecoderTest {

    private fun check(jpegHex: String, expectedHex: String, w: Int, h: Int, name: String) {
        val bm = KiteImage.decode(hex(jpegHex))
        assertEquals(w, bm.width, "$name width")
        assertEquals(h, bm.height, "$name height")
        val expected = hex(expectedHex)
        for (y in 0 until h) for (x in 0 until w) {
            val e = y * w + x
            val exp = (0xFF shl 24) or
                ((expected[e * 3].toInt() and 0xFF) shl 16) or
                ((expected[e * 3 + 1].toInt() and 0xFF) shl 8) or
                (expected[e * 3 + 2].toInt() and 0xFF)
            assertEquals(exp, bm[x, y], "$name ($x,$y)")
        }
    }

