        val whole = hex("ffd8fffe00104c61766336322e31312e31303000ffdb0043000806060706070808080808080909090a0a0a090909090a0a0a0a0a0a0c0c0c0a0a0a0a0a0a0a0c0c0c0c0d0e0d0d0d0c0d0e0e0f0f0f1212111115151519191fffc4006400010101000000" +
            "000000000000000000000603050101010000000000000000000000000000020610000105000301000000000000000000000022030602a1170752421100000502070100000000000000000000005105060111020415f06191522332ffc000110800070009" +
            "03012200021100031100ffda000c03010002110311003f009c7fad9a4a69830e366bcd30d58ffc0bc91bd53155fbd721335cca996c7b75329dc7ffd9")
        for (cut in intArrayOf(1, 2, 4, 20, 60, whole.size / 2, whole.size - 3)) {
